_satellite.__registerScript('https://assets.adobedtm.com/79b3942b8dfa/604ce2434de1/58216e635e6a/RCe5e0b6aa703946119a10b7aef2602218-source.min.js', "<!--<script defer type=\"text/javascript\" src=\"https://chat.conversica.com/widget/chatLoader.min.js\" data-clientid=\"119938\" data-assistantid=\"0\"></script>-->\n<script>\n  function onFirstUserInteraction(callback) {\n    let triggered = false;\n\n    function handler() {\n      if (triggered) return;\n      triggered = true;\n\n      window.removeEventListener(\"mousemove\", handler);\n      window.removeEventListener(\"mousedown\", handler);\n      window.removeEventListener(\"keydown\", handler);\n      window.removeEventListener(\"touchstart\", handler);\n      window.removeEventListener(\"scroll\", handler, true);\n\n      callback();\n    }\n\n    window.addEventListener(\"mousemove\", handler);\n    window.addEventListener(\"mousedown\", handler);\n    window.addEventListener(\"keydown\", handler);\n    window.addEventListener(\"touchstart\", handler);\n    window.addEventListener(\"scroll\", handler, true);\n  }\n\n    // only load Conversica above our \"md\" container breakpoint\n  if (window.innerWidth > 448) {\n    onFirstUserInteraction(function () {\n      if (localStorage.debug) console.log(\"[conversica] load script\");\n      const script = document.createElement(\"script\");\n      script.src = \"https://chat.conversica.com/widget/chatLoader.min.js\";\n      script.type = \"text/javascript\";\n      script.defer = true;\n      script.setAttribute(\"data-clientid\", \"119938\");\n      script.setAttribute(\"data-assistantid\", \"0\");\n      document.head.appendChild(script);\n    });\n  }\n</script>\n");